insert into public.products (id, name, slug, short_description, description, price, credit_price, image, category_id, brand, keywords, variations, featured, best_seller, gift_section, available, active, catalog_order, created_at) values
('p-01', 'Batom Matte Vermelho Clássico', 'batom-matte-vermelho-classico', 'Cor intensa com acabamento matte confortável.', 'Um vermelho atemporal de altíssima pigmentação. A textura cremosa desliza sem pesar nos lábios e seca em um acabamento matte veludo de longa duração, com vitamina E para evitar a sensação de ressecamento.', 39.9, 42.9, '/images/produtos/batom-matte-vermelho.png', 'cat-1', 'Cris Martins Studio', ARRAY['batom','labial','matte','vermelho','boca']::text[], ARRAY['Vermelho Clássico','Rosé Nude','Vinho Profundo']::text[], true, true, false, true, true, 0, '2026-07-28T00:00:00Z'),
('p-02', 'Base Fluida Alta Cobertura', 'base-fluida-alta-cobertura', 'Cobertura construível com efeito natural.', 'Base de textura fluida que se adapta à pele e oferece cobertura média a alta sem marcar linhas de expressão. Controla a oleosidade por até 12 horas e deixa um acabamento acetinado uniforme.', 89.9, 95.9, '/images/produtos/base-fluida-alta-cobertura.png', 'cat-1', 'Cris Martins Studio', ARRAY['base','foundation','pele','cobertura','rosto']::text[], ARRAY['Claro 20','Médio 40','Escuro 60']::text[], true, true, false, true, true, 1, '2026-07-20T00:00:00Z'),
('p-03', 'Paleta de Sombras Nude', 'paleta-de-sombras-nude', 'Doze tons neutros do dia à noite.', 'Paleta com doze tons neutros entre mattes, acetinados e cintilantes. A fórmula de alta pigmentação permite esfumar com facilidade e construir desde o olhar mais discreto até o mais marcante.', 129.9, 139.9, '/images/produtos/paleta-de-sombras-nude.png', 'cat-1', 'Cris Martins Studio', ARRAY['sombra','paleta','olhos','nude','esfumado']::text[], null, true, false, false, true, true, 2, '2026-08-04T00:00:00Z'),
('p-04', 'Máscara de Cílios Volume', 'mascara-de-cilios-volume', 'Volume imediato sem borrar.', 'Escova de cerdas curvas que separa e alonga cada fio. A fórmula à prova de umidade entrega volume desde a primeira camada e permanece intacta durante todo o dia.', 54.9, 59.9, '/images/produtos/mascara-de-cilios-volume.png', 'cat-1', 'Cris Martins Studio', ARRAY['máscara','cílios','volume','rímel','olhos']::text[], null, false, true, false, true, true, 3, '2026-06-30T00:00:00Z'),
('p-05', 'Blush Compacto Pêssego', 'blush-compacto-pessego', 'Rubor natural com brilho suave.', 'Blush compacto de textura sedosa que se mistura à pele com naturalidade. O tom pêssego ilumina o rosto e funciona em diferentes subtons, com fixação de longa duração.', 44.9, 47.9, '/images/produtos/blush-compacto-pessego.png', 'cat-1', 'Cris Martins Studio', ARRAY['blush','rubor','pêssego','bochecha','rosto']::text[], null, false, false, false, true, true, 4, '2026-05-18T00:00:00Z'),
('p-06', 'Perfume Floral Elegance', 'perfume-floral-elegance', 'Fragrância delicada e marcante.', 'Eau de parfum floral construído sobre notas de peônia e jasmim, com fundo amadeirado de âmbar e musk. Uma assinatura feminina sofisticada com até 10 horas de fixação.', 189.9, 204.9, '/images/produtos/perfume-floral-elegance.png', 'cat-2', 'Maison Elegance', ARRAY['perfume','floral','fragrância','eau de parfum','feminino']::text[], ARRAY['50ml','100ml']::text[], true, true, false, true, true, 5, '2026-08-09T00:00:00Z'),
('p-07', 'Eau de Parfum Âmbar Noir', 'eau-de-parfum-ambar-noir', 'Amadeirado intenso para a noite.', 'Composição oriental com abertura de bergamota, coração de íris e fundo profundo de âmbar, baunilha e patchouli. Presença marcante, ideal para eventos e noites especiais.', 249.9, 269.9, '/images/produtos/eau-de-parfum-ambar-noir.png', 'cat-2', 'Maison Elegance', ARRAY['perfume','âmbar','amadeirado','noite','intenso']::text[], ARRAY['50ml','100ml']::text[], true, false, false, true, true, 6, '2026-08-12T00:00:00Z'),
('p-08', 'Body Splash Baunilha', 'body-splash-baunilha', 'Perfume leve para o dia a dia.', 'Body splash de baunilha cremosa com toque de amêndoas. Refrescante e discreto, pode ser reaplicado ao longo do dia e combina perfeitamente com o creme corporal da mesma linha.', 59.9, 64.9, '/images/produtos/body-splash-baunilha.png', 'cat-2', 'Cris Martins Studio', ARRAY['body splash','baunilha','perfume','corpo','colônia']::text[], null, false, true, false, true, true, 7, '2026-06-12T00:00:00Z'),
('p-09', 'Perfume Cítrico Fresh', 'perfume-citrico-fresh', 'Frescor cítrico e sofisticado.', 'Fragrância vibrante com limão siciliano, bergamota e notas verdes de chá branco. Leve e elegante, perfeita para o clima quente e para o uso diário.', 159.9, 174.9, '/images/produtos/perfume-citrico-fresh.png', 'cat-2', 'Maison Elegance', ARRAY['perfume','cítrico','fresh','leve','verão']::text[], null, false, false, false, true, true, 8, '2026-05-30T00:00:00Z'),
('p-10', 'Óleo Capilar Reparador', 'oleo-capilar-reparador', 'Brilho e reparação das pontas.', 'Blend de óleos de argan, macadâmia e coco que sela as cutículas, reduz o frizz e devolve brilho aos fios. Textura seca, absorção rápida e sem efeito pesado.', 74.9, 79.9, '/images/produtos/oleo-capilar-reparador.png', 'cat-3', 'Atelier Capilar', ARRAY['óleo','cabelo','reparador','frizz','brilho','finalizador']::text[], null, true, false, false, true, true, 9, '2026-08-14T00:00:00Z'),
('p-11', 'Máscara de Nutrição Intensa', 'mascara-de-nutricao-intensa', 'Nutrição profunda em 5 minutos.', 'Máscara de tratamento com manteiga de karité e proteínas da seda. Recupera fios secos e quimicamente tratados, deixando o cabelo macio e maleável desde a primeira aplicação.', 89.9, 95.9, '/images/produtos/mascara-nutricao-intensa.png', 'cat-3', 'Atelier Capilar', ARRAY['máscara','cabelo','nutrição','hidratação','tratamento']::text[], null, false, true, false, true, true, 10, '2026-07-02T00:00:00Z'),
('p-12', 'Leave-in Protetor Térmico', 'leave-in-protetor-termico', 'Proteção contra o calor até 220°C.', 'Spray leve que protege os fios do secador, chapinha e babyliss. Facilita o desembaraço, controla o volume e não deixa resíduo.', 64.9, 69.9, '/images/produtos/leave-in-protetor-termico.png', 'cat-3', 'Atelier Capilar', ARRAY['leave-in','protetor térmico','cabelo','spray','chapinha']::text[], null, false, false, false, true, true, 11, '2026-04-22T00:00:00Z'),
('p-13', 'Sérum Facial Vitamina C', 'serum-facial-vitamina-c', 'Viço e uniformidade para a pele.', 'Sérum com 10% de vitamina C estabilizada e ácido ferúlico. Reduz manchas, ilumina o tom da pele e protege contra os radicais livres. Uso diário pela manhã, antes do protetor solar.', 119.9, 129.9, '/images/produtos/serum-vitamina-c.png', 'cat-4', 'Dermalab', ARRAY['sérum','vitamina c','skincare','manchas','viço','rosto']::text[], null, true, true, false, true, true, 12, '2026-08-15T00:00:00Z'),
('p-14', 'Hidratante Facial Ácido Hialurônico', 'hidratante-facial-acido-hialuronico', 'Hidratação leve por 24 horas.', 'Gel-creme com três pesos moleculares de ácido hialurônico que hidratam em diferentes camadas da pele. Textura fresca, rápida absorção e ideal sob a maquiagem.', 99.9, 109.9, '/images/produtos/hidratante-facial-acido-hialuronico.png', 'cat-4', 'Dermalab', ARRAY['hidratante','ácido hialurônico','skincare','gel creme','rosto']::text[], null, false, true, false, true, true, 13, '2026-07-11T00:00:00Z'),
('p-15', 'Protetor Solar Toque Seco FPS 50', 'protetor-solar-toque-seco-fps-50', 'Alta proteção com toque seco.', 'Protetor solar facial FPS 50 com acabamento invisível e efeito matificante. Não deixa resíduo branco e pode ser usado como base para a maquiagem.', 84.9, 92.9, '/images/produtos/protetor-solar-toque-seco.png', 'cat-4', 'Dermalab', ARRAY['protetor solar','fps 50','skincare','toque seco','facial']::text[], null, false, false, false, false, true, 14, '2026-06-05T00:00:00Z'),
('p-16', 'Água Micelar Suave', 'agua-micelar-suave', 'Limpeza delicada sem enxágue.', 'Remove maquiagem, oleosidade e impurezas em um único passo, sem agredir a barreira cutânea. Fórmula sem perfume, indicada até para pele sensível.', 49.9, 54.9, '/images/produtos/agua-micelar-suave.png', 'cat-4', 'Dermalab', ARRAY['água micelar','limpeza','demaquilante','skincare','pele sensível']::text[], null, false, false, false, true, true, 15, '2026-03-28T00:00:00Z'),
('p-17', 'Creme Corporal Karité', 'creme-corporal-karite', 'Hidratação rica e prolongada.', 'Creme corporal denso com manteiga de karité e óleo de amêndoas. Restaura a maciez de pernas, braços e áreas mais secas, com perfume suave e envolvente.', 69.9, 74.9, '/images/produtos/creme-corporal-karite.png', 'cat-5', 'Cris Martins Studio', ARRAY['creme','corporal','karité','hidratante','corpo']::text[], null, true, false, false, true, true, 16, '2026-08-01T00:00:00Z'),
('p-18', 'Sabonete Líquido de Rosas', 'sabonete-liquido-de-rosas', 'Espuma delicada e perfumada.', 'Sabonete líquido com extrato de rosas e glicerina vegetal. Limpa suavemente e mantém a pele hidratada, deixando um perfume floral discreto após o banho.', 42.9, 46.9, '/images/produtos/sabonete-liquido-rosas.png', 'cat-5', 'Cris Martins Studio', ARRAY['sabonete','líquido','rosas','banho','corpo']::text[], null, false, true, false, true, true, 17, '2026-05-09T00:00:00Z'),
('p-19', 'Kit de Pincéis Profissional', 'kit-de-pinceis-profissional', 'Doze pincéis para rosto e olhos.', 'Kit com doze pincéis de cerdas sintéticas ultramacias para base, pó, blush, contorno e olhos. Cabos em rosé com virola dourada e estojo para transporte.', 179.9, 194.9, '/images/produtos/kit-pinceis-profissional.png', 'cat-6', 'Cris Martins Studio', ARRAY['pincéis','kit','acessórios','maquiagem','brushes']::text[], null, true, true, true, true, true, 18, '2026-08-16T00:00:00Z'),
('p-20', 'Necessaire Rosé', 'necessaire-rose', 'Organização com acabamento premium.', 'Necessaire matelassê em cetim rosé com zíper dourado e forro impermeável. Tamanho ideal para viagens e para manter os essenciais sempre organizados.', 89.9, 97.9, '/images/produtos/necessaire-rose.png', 'cat-6', 'Cris Martins Studio', ARRAY['necessaire','organizador','acessórios','viagem','rosé']::text[], null, false, false, false, true, true, 19, '2026-07-24T00:00:00Z'),
('p-21', 'Kit Presente Completo', 'kit-presente-completo', 'Uma seleção especial pronta para presentear.', 'Kit presenteável com uma seleção de itens pensados para surpreender em datas especiais. Uma opção prática, elegante e pronta para transformar o presente em uma experiência completa.', 149.9, 159.9, '/images/produtos/kit-presente-completo.png', 'cat-6', 'Cris Martins Studio', ARRAY['kit','presente','presenteável','combo','especial']::text[], null, false, false, true, true, true, 20, '2026-07-15T00:00:00Z'),
('p-22', 'Bolsa Feminina Rosé', 'bolsa-feminina-rose', 'Elegância e praticidade para todos os momentos.', 'Bolsa feminina em acabamento rosé com design elegante e versátil. Espaço interno organizado e tamanho ideal para acompanhar a rotina ou compor um presente especial.', 119.9, 129.9, '/images/produtos/bolsa-feminina-rose..png', 'cat-6', 'Cris Martins Studio', ARRAY['bolsa','acessórios','feminino','presente','rosé']::text[], null, false, false, true, true, true, 21, '2026-07-10T00:00:00Z'),
('p-23', 'Urso Presenteável', 'urso-presenteavel', 'Um carinho especial para tornar o presente inesquecível.', 'Urso de pelúcia com acabamento delicado, pensado para complementar kits e presentes especiais. Uma escolha afetiva para aniversários e outras ocasiões.', 89.9, 97.9, '/images/produtos/urso-presenteavel..png', 'cat-6', 'Cris Martins Studio', ARRAY['urso','pelúcia','presente','kit','romântico']::text[], null, false, false, true, true, true, 22, '2026-07-05T00:00:00Z')
